function createSampleBook(){const spreads=SAMPLE_CHAPTERS.map((c,i)=>{const photo={id:crypto.randomUUID(),type:c[6]==='video'?'video':'photo',text:c[4],url:c[6]==='video'?'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4':'https://images.unsplash.com/'+SAMPLE_PHOTOS[c[5]]+'?w=700&auto=format&fit=crop&q=80',x:57,y:43,w:33,tilt:i%2?-4:4,color:'#ffffff',font:20};const pieces=[photo];if(i%3===0||c[6]==='cardboard'||c[6]==='ticket')pieces.push({id:crypto.randomUUID(),type:c[6]==='video'?'note':c[6],text:({note:'Small things count.',ticket:'ADMIT ONE\nA day worth keeping',cardboard:'A thought to come back to.',paper:'Keep the rough edges.',tape:'remember this'})[c[6]]||'Keep this moment.',x:10,y:68,w:24,tilt:-5,color:c[6]==='cardboard'?'#cba77a':i%2?'#e7d9f2':'#f8ed89',font:22});return{id:crypto.randomUUID(),heading:c[0],diary:{left:c[0]+'\n\n'+c[1],right:c[2]+'\n\n'+c[3]},pieces,entryId:null}});return{id:crypto.randomUUID(),title:'The little things',subtitle:'A field guide to ordinary days',author:'A Wispr Diary sample',category:'Sample books',color:'#bca2dc',coverImage:'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?w=700&auto=format&fit=crop&q=80',coverStyle:'photo',coverFont:'serif',isSample:true,entries:[],spreads,activeSpread:0,draft:structuredClone(spreads[0]),updated:new Date().toISOString()}}
